# Mundora RPG — Streamlit + Mercado Pago (Pix e cartão)
from __future__ import annotations
import base64, hashlib, hmac, os, time
from pathlib import Path
import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title="Mundora RPG", page_icon="⚔️", layout="wide", initial_sidebar_state="expanded")
ROOT = Path(__file__).resolve().parent
_GAME_B64 = """"""

def get_secret(name, default=""):
    try:
        if name in st.secrets: return str(st.secrets[name])
    except Exception: pass
    return os.environ.get(name, default)

MP_ACCESS_TOKEN = get_secret("MP_ACCESS_TOKEN", "")
REDEEM_SECRET = get_secret("MUNDORA_REDEEM_SECRET", "mundora-dev-secret-change-me")

def load_game_html():
    for p in [ROOT/"Mundora-RPG-completo.html", Path.cwd()/"Mundora-RPG-completo.html"]:
        try:
            if p.is_file() and p.stat().st_size > 1000:
                return p.read_text(encoding="utf-8", errors="replace")
        except Exception: pass
    return base64.b64decode(_GAME_B64.encode("ascii")).decode("utf-8", errors="replace")

def make_redeem_code(item_id: str) -> str:
    ts = str(int(time.time()) // 3600)
    raw = f"{item_id}|{ts}|{REDEEM_SECRET}"
    token = hmac.new(REDEEM_SECRET.encode(), raw.encode(), hashlib.sha256).hexdigest()[:8].upper()
    return f"MND-{item_id}-{token}"

def create_mp_preference(item_id, title, amount, method="pix"):
    if not MP_ACCESS_TOKEN:
        return {"error": "MP_ACCESS_TOKEN não configurado (Streamlit Secrets)."}
    try:
        import mercadopago
    except ImportError:
        return {"error": "Instale mercadopago: pip install mercadopago"}
    sdk = mercadopago.SDK(MP_ACCESS_TOKEN)
    preference_data = {
        "items": [{"id": item_id, "title": title[:120], "quantity": 1, "currency_id": "BRL", "unit_price": float(round(amount, 2))}],
        "statement_descriptor": "MUNDORA RPG",
        "external_reference": item_id,
        "metadata": {"item_id": item_id, "method_hint": method},
        "payment_methods": {"installments": 12, "default_installments": 1},
    }
    if method == "pix":
        preference_data["payment_methods"]["default_payment_method_id"] = "pix"
    try:
        result = sdk.preference().create(preference_data)
        resp = result.get("response") or {}
        if result.get("status") not in (200, 201):
            return {"error": str(resp.get("message") or result)}
        return {"init_point": resp.get("init_point") or resp.get("sandbox_init_point"), "sandbox_init_point": resp.get("sandbox_init_point")}
    except Exception as e:
        return {"error": str(e)}

PREMIUM_CATALOG = [
    ("skin_knight_gold", "Cavaleiro Dourado", 9.90),
    ("spell_firebolt", "Seta Ígnea", 9.90),
    ("rune_sword", "Espada Rúnica", 9.90),
    ("frost_staff", "Cajado Gélido", 9.90),
    ("spell_heal", "Mão Curativa", 9.90),
    ("spell_barrier", "Barreira Arcana", 9.90),
    ("skin_shadow_assassin", "Assassino das Sombras", 14.90),
    ("skin_sky_pilot", "Piloto de Sohhen", 14.90),
    ("crystal_blade", "Lâmina de Cristal", 14.90),
    ("spell_shadow", "Lâmina Sombria", 14.90),
    ("spell_ice", "Lança de Gelo", 12.90),
    ("skin_archmage", "Arquimago Celeste", 19.90),
    ("thunder_hammer", "Martelo do Trovão", 19.90),
    ("sky_glaive", "Glaive Celeste", 19.90),
    ("spell_lightning", "Raio Celeste", 19.90),
    ("skin_star_guardian", "Guardião Estelar", 24.90),
    ("phoenix_bow", "Arco Fênix", 24.90),
    ("skin_dragon_lord", "Senhor Dragão", 29.90),
    ("void_scythe", "Foice do Vazio", 29.90),
    ("spell_star", "Chuva Estelar", 29.90),
    ("spell_void", "Ruptura do Vazio", 39.90),
    ("skin_void_walker", "Andarilho do Vazio", 49.90),
    ("pack_iniciante", "Pacote Iniciante", 9.90),
    ("pack_floresta", "Pacote Floresta", 39.90),
    ("pack_lenda", "Pacote Lenda", 79.90),
]

st.markdown('<style>.block-container{padding-top:0.5rem;max-width:100%}</style>', unsafe_allow_html=True)

with st.sidebar:
    st.title("⚔️ Mundora RPG")
    st.caption("Pagamentos reais: Pix e cartão")
    if MP_ACCESS_TOKEN:
        st.success("Mercado Pago configurado")
    else:
        st.warning("Defina MP_ACCESS_TOKEN nos Secrets")

    st.subheader("💎 Checkout Premium")
    labels = {f"{n} — R$ {p:.2f}".replace(".", ","): i for i, n, p in PREMIUM_CATALOG}
    choice = st.selectbox("Item", list(labels.keys()))
    item_id = labels[choice]
    title = next(n for i, n, p in PREMIUM_CATALOG if i == item_id)
    amount = next(p for i, n, p in PREMIUM_CATALOG if i == item_id)
    method = st.radio("Forma", ["pix", "card"], format_func=lambda m: "Pix" if m == "pix" else "Cartão", horizontal=True)

    if st.button("Pagar com Mercado Pago", type="primary", use_container_width=True):
        if not MP_ACCESS_TOKEN:
            st.error("Configure MP_ACCESS_TOKEN para cobrança real.")
        else:
            with st.spinner("Criando checkout..."):
                pref = create_mp_preference(item_id, title, amount, method)
            if pref.get("error"):
                st.error(pref["error"])
            else:
                code = make_redeem_code(item_id)
                st.session_state.setdefault("codes", []).append({"item": item_id, "code": code})
                st.session_state["last_code"] = code
                st.session_state["last_item"] = item_id
                url = pref.get("init_point") or pref.get("sandbox_init_point")
                st.success("Checkout criado")
                if url:
                    st.link_button("Abrir pagamento seguro", url, type="primary", use_container_width=True)

    if st.session_state.get("last_code"):
        st.info("Código para resgatar no jogo após pagar:")
        st.code(st.session_state["last_code"])
        st.caption("No jogo: Loja → colar código → Resgatar")

    st.markdown("---")
    st.markdown("""**Secrets (Streamlit Cloud)**
```toml
MP_ACCESS_TOKEN = "APP_USR-..."
MUNDORA_REDEEM_SECRET = "string-secreta-longa"
```
**requirements.txt:** `streamlit` + `mercadopago`

Cartão e Pix ficam no checkout do Mercado Pago (PCI). O app não lê dados do cartão.
""")
    altura = st.slider("Altura (px)", 600, 1400, 900, 50)

html = load_game_html()
if len(html) < 500:
    st.error("Jogo não encontrado"); st.stop()
codes = [c["code"] for c in st.session_state.get("codes", []) if c.get("code")]
inject = f"<script>window.MUNDORA_REDEEM_CODES={codes!r};window.MUNDORA_PAID_ITEM={st.session_state.get('last_item')!r};</script>"
html = html.replace("</body>", inject + "</body>", 1) if "</body>" in html else html + inject
components.html(html, height=altura, scrolling=True)
